<template>
  <div :class="['global-search', { 'is-rail': compact }]">
    <el-button class="search-trigger" round @click="open"><el-icon><Search /></el-icon><span>搜索会话、知识库、公告…</span><kbd>⌘ K</kbd></el-button>
    <el-dialog v-model="visible" width="min(980px, calc(100vw - 24px))" top="5vh" class="global-dialog" :show-close="false" append-to-body @opened="focusInput">
      <div class="search-head"><el-input ref="input" v-model="query" size="large" clearable autofocus placeholder="输入关键词，搜索会话、知识库、文档、公告、行程、工单…" :prefix-icon="Search" @keyup.enter="onEnter" @keydown.down.prevent="move(1)" @keydown.up.prevent="move(-1)" @keydown.esc="visible=false" /><el-button text circle aria-label="关闭" @click="visible=false"><el-icon><Close /></el-icon></el-button></div>
      <div class="search-tabs"><el-check-tag v-for="tab in tabs" :key="tab.key" :checked="active === tab.key" @click="active = active === tab.key ? 'all' : tab.key">{{ tab.label }}</el-check-tag><el-button text class="filter-btn" @click="filters = !filters"><el-icon><Filter /></el-icon>筛选</el-button></div>
      <div class="history" v-if="!hasSearched && history.length"><div class="section-title">搜索历史 <el-button link @click="clearHistory">清空</el-button></div><el-tag v-for="word in history" :key="word" round class="history-tag" @click="query=word;submit()">{{ word }}</el-tag></div>
      <div v-if="!hasSearched" class="search-hint"><el-empty description="输入关键词开始搜索" :image-size="80" /></div>
      <div v-else class="results-wrap" v-loading="loading"><div class="result-main"><div class="result-summary">“{{ lastQuery }}” 找到 {{ total }} 条结果</div><section v-for="group in resultGroups" :key="group.key" v-show="group.items.length" class="result-group"><div class="section-title">{{ group.label }} <span>{{ group.items.length }}</span></div><button v-for="(item, index) in group.items" :key="`${group.key}-${item.id}`" :class="['result-item',{active:selected===index}]" @click="navigate(item.route)"><div class="result-icon">{{ group.icon }}</div><div class="result-text"><strong>{{ item.title }}</strong><p>{{ item.snippet || '暂无摘要' }}</p></div><small>{{ time(item.updated_at) }}</small></button></section><el-empty v-if="!total" description="没有找到匹配记录" :image-size="100" /></div><aside v-if="filters" class="filter-panel"><div class="section-title">筛选 <el-button link @click="filters=false">关闭</el-button></div><el-checkbox-group v-model="filterTypes"><el-checkbox v-for="tab in tabs" :key="tab.key" :value="tab.key">{{ tab.label }}</el-checkbox></el-checkbox-group><el-button type="primary" class="apply" @click="submit">应用筛选</el-button></aside></div>
      <template #footer><span class="search-foot">↑↓ 导航　Enter 打开　Esc 关闭</span></template>
    </el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { Search, Close, Filter } from '@element-plus/icons-vue'
import { globalSearch, type SearchItem, type SearchKind } from '@/api/globalSearch'
defineProps<{ compact?: boolean }>()
const router = useRouter(), visible = ref(false), query = ref(''), lastQuery = ref(''), loading = ref(false), filters = ref(false), active = ref('all'), filterTypes = ref<SearchKind[]>([]), result = ref<Record<string, SearchItem[]>>({}), total = ref(0), selected = ref(-1), input = ref()
const tabs: { key: SearchKind; label: string; icon: string }[] = [{key:'conversations',label:'会话',icon:'💬'},{key:'messages',label:'消息',icon:'✉'},{key:'knowledge',label:'知识库',icon:'📖'},{key:'documents',label:'文档',icon:'📄'},{key:'contacts',label:'联系人',icon:'👤'},{key:'announcements',label:'公告',icon:'📢'},{key:'calendar',label:'行程',icon:'🗓'},{key:'tickets',label:'工单',icon:'🎫'},{key:'memos',label:'备忘',icon:'📝'}]
const resultGroups = computed(() => tabs.map(t => ({ ...t, items: result.value[t.key] || [] })).filter(g => active.value === 'all' || active.value === g.key))
const hasSearched = computed(() => !!lastQuery.value)
const history = ref<string[]>(readHistory())
function readHistory(): string[] { try { const value = JSON.parse(localStorage.getItem('omni-search-history') || '[]'); return Array.isArray(value) ? value.filter((x): x is string => typeof x === 'string').slice(0, 8) : [] } catch { return [] } }
function open() { visible.value = true; nextTick(focusInput) }
function focusInput() { input.value?.focus?.() }
async function submit() { const q = query.value.trim(); if (!q) return; loading.value = true; lastQuery.value = q; history.value = [q, ...history.value.filter(x => x !== q)].slice(0, 8); localStorage.setItem('omni-search-history', JSON.stringify(history.value)); try { const types = filterTypes.value.length ? filterTypes.value : active.value !== 'all' ? [active.value as SearchKind] : undefined; const data = await globalSearch(q, types); result.value = data.results; total.value = data.total; selected.value = -1 } catch { ElMessage.error('搜索失败，请稍后重试') } finally { loading.value = false } }
function move(delta: number) { const all = resultGroups.value.flatMap(g => g.items); if (!all.length) return; selected.value = (selected.value + delta + all.length) % all.length }
function onEnter() { const all = resultGroups.value.flatMap(g => g.items); if (selected.value >= 0 && all[selected.value]) navigate(all[selected.value].route); else void submit() }
function navigate(route: string) { visible.value = false; if (route.startsWith('http')) window.open(route, '_blank', 'noopener'); else router.push(route) }
function clearHistory() { history.value = []; localStorage.removeItem('omni-search-history') }
function time(value?: string) { if (!value) return ''; const d = new Date(value); return Number.isNaN(d.getTime()) ? '' : d.toLocaleDateString('zh-CN') }
function keydown(e: KeyboardEvent) { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); open() } }
onMounted(() => window.addEventListener('keydown', keydown)); onUnmounted(() => window.removeEventListener('keydown', keydown))
</script>
<style scoped>
.search-trigger{width:300px;justify-content:flex-start;color:#6b7280;border-color:#d9e2ec;background:#fff}.search-trigger span{margin:0 10px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.search-trigger kbd{margin-left:auto;font-size:11px;color:#9aa5b1;background:#f3f6f9;border-radius:4px;padding:2px 5px}.search-head{display:flex;gap:8px;align-items:center}.search-tabs{display:flex;gap:8px;flex-wrap:wrap;border-bottom:1px solid #edf0f4;padding:14px 0}.search-tabs :deep(.el-check-tag){cursor:pointer;padding:7px 13px;border-radius:16px}.filter-btn{margin-left:auto}.history,.search-hint{padding:20px 0}.section-title{display:flex;align-items:center;gap:8px;color:#344054;font-weight:600;margin-bottom:10px}.section-title .el-button{margin-left:auto;font-weight:normal}.history-tag{margin:0 8px 8px 0;cursor:pointer}.results-wrap{display:flex;min-height:470px}.result-main{flex:1;padding:16px 10px 20px 0;overflow:auto;max-height:60vh}.result-summary{color:#667085;font-size:13px;margin-bottom:16px}.result-group{margin-bottom:18px}.result-group .section-title span{color:#98a2b3;font-weight:normal}.result-item{display:flex;align-items:center;gap:12px;width:100%;padding:10px;border:0;border-radius:7px;background:transparent;text-align:left;cursor:pointer}.result-item:hover,.result-item.active{background:#f1f6ff}.result-icon{width:30px;text-align:center;font-size:18px}.result-text{min-width:0;flex:1}.result-text strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#1d2939}.result-text p{margin:3px 0 0;color:#667085;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:13px}.result-item small{color:#98a2b3;white-space:nowrap}.filter-panel{width:230px;border-left:1px solid #edf0f4;padding:16px}.filter-panel :deep(.el-checkbox){display:flex;margin:0 0 14px}.apply{width:100%;margin-top:20px}.search-foot{color:#98a2b3;font-size:12px}.global-dialog :deep(.el-dialog__body){padding:0 22px}.global-dialog :deep(.el-dialog__footer){padding-top:8px}@media(max-width:700px){.search-trigger{width:42px;padding:0;justify-content:center}.search-trigger span,.search-trigger kbd{display:none}.results-wrap{min-height:350px}.filter-panel{position:absolute;right:0;background:#fff;height:100%;z-index:2}}
.is-rail{width:44px;height:44px;display:flex;align-items:center;justify-content:center}.is-rail .search-trigger{width:44px;height:44px;padding:0;justify-content:center;border:0;border-radius:8px;background:transparent;color:rgba(255,255,255,.85)}.is-rail .search-trigger:hover{background:rgba(255,255,255,.16);color:#fff}.is-rail .search-trigger span,.is-rail .search-trigger kbd{display:none}.is-rail .search-trigger :deep(.el-icon){font-size:22px}
</style>
